window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-99dc75a2b049f0de"]={"versions": [{"id": "FIG-99dc75a2b049f0de", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P11Forward</code> im Rahmen des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm modelliert das Verhalten bei der Weiterleitung bzw. erneuten Absicherung von E2E-geschützten Nutzdaten auf Kommunikations- oder Gateway-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Entry Point</strong>: <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code></li>\n<li><strong>Eingangs- / Zustandsstrukturen</strong>:</li>\n<li><code>Config</code>: Konfigurationsparameter des E2E-Profils 11</li>\n<li><code>State</code>: Dynamischer Zustandsvektor (u. a. interner Zählerstand)</li>\n<li><code>Data</code>: Zu schützender Datenpuffer</li>\n<li><code>Length</code>: Datenlänge</li>\n<li><code>CheckStatus</code>: Status einer vorangegangenen Prüfung</li>\n<li><strong>Sub-Aktivitäten (Aufrufaktionen)</strong>:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Write DataIDNibble</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Kontrollknoten</strong>:</li>\n<li>Initialknoten</li>\n<li>Verzweigung mit Guards <code>[input ok]</code> und <code>[wrong input]</code></li>\n<li>Drei Aktivitätsendknoten mit Rücksprung (<code>return</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start über Initialknoten bei Aufruf von <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code>.</li>\n<li>Ausführung der Aktion <code>Verify inputs of the protect function</code>.</li>\n<li>Verzweigung anhand der Eingangsparameter:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhaften Eingaben (<code>[wrong input]</code>): Verzweigung nach links oder rechts zu einem Aktivitätsendknoten und sofortiges Beenden (<code>return</code>).</li>\n<li>Bei gültigen Eingaben (<code>[input ok]</code>): Sequenzielle Ausführung der Profil-11-Schritte:</li>\n</ul>\n<p class=\"fig-p\">a. <code>Write DataIDNibble</code>: Schreiben des Data-ID-Nibbles in den Datenpuffer.</p>\n<p class=\"fig-p\">b. <code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in die Payload.</p>\n<p class=\"fig-p\">c. <code>Compute CRC</code>: Berechnung der CRC über die Daten inklusive Data-ID.</p>\n<p class=\"fig-p\">d. <code>Write CRC</code>: Eintragen der berechneten CRC in den Datenpuffer.</p>\n<p class=\"fig-p\">e. <code>Increment Counter</code>: Inkrementieren des Zählers für die nachfolgende Übertragung.</p>\n<ol class=\"fig-list\">\n<li>Reguläres Beenden der Funktion über den zentralen Aktivitätsendknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ verbindlicher Kontrollfluss für die Implementierung der Funktion <code>E2E_P11Forward</code>.</li>\n<li>Eingangsvalidierung (<code>Verify inputs of the protect function</code>) ist zwingend vor jeglicher Datenmodifikation durchzuführen; bei ungültigen Eingaben darf keine Veränderung des Puffers (<code>Data</code>) oder Zählerstands (<code>State</code>) erfolgen.</li>\n<li>Die Schritte <code>Write DataIDNibble</code> und <code>Write Counter</code> müssen vor <code>Compute CRC</code> ausgeführt werden, da beide Werte in die CRC-Berechnung einfließen.</li>\n<li><code>Increment Counter</code> darf erst nach erfolgreicher CRC-Erzeugung und Pufferbeschriftung erfolgen.</li>\n</ul>"}, {"id": "FIG-c1e7f71d05f5548e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P11Forward</code> im Rahmen des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm modelliert das Verhalten bei der Weiterleitung bzw. erneuten Absicherung von E2E-geschützten Nutzdaten auf Kommunikations- oder Gateway-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Entry Point</strong>: <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code></li>\n<li><strong>Eingangs- / Zustandsstrukturen</strong>:</li>\n<li><code>Config</code>: Konfigurationsparameter des E2E-Profils 11</li>\n<li><code>State</code>: Dynamischer Zustandsvektor (u. a. interner Zählerstand)</li>\n<li><code>Data</code>: Zu schützender Datenpuffer</li>\n<li><code>Length</code>: Datenlänge</li>\n<li><code>CheckStatus</code>: Status einer vorangegangenen Prüfung</li>\n<li><strong>Sub-Aktivitäten (Aufrufaktionen)</strong>:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Write DataIDNibble</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Kontrollknoten</strong>:</li>\n<li>Initialknoten</li>\n<li>Verzweigung mit Guards <code>[input ok]</code> und <code>[wrong input]</code></li>\n<li>Drei Aktivitätsendknoten mit Rücksprung (<code>return</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start über Initialknoten bei Aufruf von <code>E2E_P11Forward(Config, State, Data, Length, CheckStatus)</code>.</li>\n<li>Ausführung der Aktion <code>Verify inputs of the protect function</code>.</li>\n<li>Verzweigung anhand der Eingangsparameter:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhaften Eingaben (<code>[wrong input]</code>): Verzweigung nach links oder rechts zu einem Aktivitätsendknoten und sofortiges Beenden (<code>return</code>).</li>\n<li>Bei gültigen Eingaben (<code>[input ok]</code>): Sequenzielle Ausführung der Profil-11-Schritte:</li>\n</ul>\n<p class=\"fig-p\">a. <code>Write DataIDNibble</code>: Schreiben des Data-ID-Nibbles in den Datenpuffer.</p>\n<p class=\"fig-p\">b. <code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in die Payload.</p>\n<p class=\"fig-p\">c. <code>Compute CRC</code>: Berechnung der CRC über die Daten inklusive Data-ID.</p>\n<p class=\"fig-p\">d. <code>Write CRC</code>: Eintragen der berechneten CRC in den Datenpuffer.</p>\n<p class=\"fig-p\">e. <code>Increment Counter</code>: Inkrementieren des Zählers für die nachfolgende Übertragung.</p>\n<ol class=\"fig-list\">\n<li>Reguläres Beenden der Funktion über den zentralen Aktivitätsendknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ verbindlicher Kontrollfluss für die Implementierung der Funktion <code>E2E_P11Forward</code>.</li>\n<li>Eingangsvalidierung (<code>Verify inputs of the protect function</code>) ist zwingend vor jeglicher Datenmodifikation durchzuführen; bei ungültigen Eingaben darf keine Veränderung des Puffers (<code>Data</code>) oder Zählerstands (<code>State</code>) erfolgen.</li>\n<li>Die Schritte <code>Write DataIDNibble</code> und <code>Write Counter</code> müssen vor <code>Compute CRC</code> ausgeführt werden, da beide Werte in die CRC-Berechnung einfließen.</li>\n<li><code>Increment Counter</code> darf erst nach erfolgreicher CRC-Erzeugung und Pufferbeschriftung erfolgen.</li>\n</ul>"}], "trans": [{"from": "FIG-99dc75a2b049f0de", "to": "FIG-c1e7f71d05f5548e", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
